hall_id'<>'null'::jsonb OR hall_evidence->'selected_hall_id'<>'null'::jsonb\n    OR hall_evidence->'warehouse_hall_id_at_capture'<>'null'::jsonb OR hall_evidence->'has_difference'<>'false'::jsonb OR hall_evidence->'review_required'<>'true'::jsonb)) THEN\n  RAISE EXCEPTION 'HISTORICAL_HALL_EVIDENCE_CONTRADICTION' USING ERRCODE='23514'; END IF;\n\n     IF hall_evidence->'selected_hall_id' IS DISTINCT FROM coalesce(to_jsonb(NEW.hall_id),'null'::jsonb)\n      OR hall_evidence->>'warehouse_id' IS DISTINCT FROM NEW.warehouse_id::text\n      OR jsonb_typeof(source.normalized_fields->'所属厅来源编号') IS DISTINCT FROM 'string'\n      OR (hall_evidence->'original_hall_id'='null'::jsonb AND source.normalized_fields->>'所属厅来源编号'<>'')\n      OR (hall_evidence->'original_hall_id'<>'null'::jsonb AND (source.normalized_fields->>'所属厅来源编号'='' OR NOT EXISTS(\n       SELECT 1 FROM naijue_erp.import_header_native_reference ref WHERE ref.batch_id=NEW.batch_id AND ref.entity_type='HALL'\n        AND ref.source_key=source.normalized_fields->>'所属厅来源编号' AND ref.native_hall_id=(hall_evidence->>'original_hall_id')::uuid))) THEN\n      RAISE EXCEPTION 'HISTORICAL_SALES_HALL_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;\n     IF hall_evidence->'warehouse_version'<>'null'::jsonb AND NOT EXISTS(SELECT 1 FROM naijue_erp.warehouse w\n      WHERE w.id=NEW.warehouse_id AND w.version=(hall_evidence->>'warehouse_version')::integer\n       AND to_jsonb(w.hall_id) IS NOT DISTINCT FROM hall_evidence->'warehouse_hall_id_at_capture') THEN\n      RAISE EXCEPTION 'HISTORICAL_HALL_CAPTURE_CHANGED' USING ERRCODE='23514'; END IF;\n    END;\n   ELSE\n    -- Historical consumers that did not opt into inference retain their strict source contract.\n    IF jsonb_typeof(source.normalized_fields->'所属厅来源编号') IS DISTINCT FROM 'string'\n      OR (source.normalized_fields->>'所属厅来源编号'='' AND NEW.hall_id IS NOT NULL)\n      OR (source.normalized_fields->>'所属厅来源编号'<>'' AND (NEW.hall_id IS NULL OR NOT EXISTS(\n        SELECT 1 FROM